package com.vandorlabs.neoforge.legacylanding;
import com.vandorlabs.gear.core.LegacyLandingLayout;
import com.vandorlabs.neoforge.transfer.NativeRawCell;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.state.BlockState;
/** Same-root reservation edits only. This class cannot adopt a payload or consume an inventory slot. */
final class NativeLegacyFootprints {
 private record Scope(Level level,BlockPos root){}
 private static final ThreadLocal<Scope> ACTIVE=new ThreadLocal<>();
 static void withoutCleanup(Level world,BlockPos root,Runnable action){var prior=ACTIVE.get();ACTIVE.set(new Scope(world,root));try{action.run();}finally{if(prior==null)ACTIVE.remove();else ACTIVE.set(prior);}}
 static boolean mutating(Level level,BlockPos pos){if(com.vandorlabs.neoforge.placement.NativeStationaryPlacement.mutating(level,pos))return true;var scope=ACTIVE.get();return scope!=null&&scope.level==level&&Math.abs((long)pos.getX()-scope.root.getX())<=1&&Math.abs((long)pos.getZ()-scope.root.getZ())<=1&&pos.getY()<=scope.root.getY()&&scope.root.getY()-pos.getY()<=5;}
 static boolean declared(NativeLegacyLandingEntity root,BlockPos pos){var delta=pos.subtract(root.getBlockPos());int size=root.settings().size(),depth=LegacyLandingLayout.depth(Math.max(root.progress(),root.targetDistance()),size),radius=size>=3?1:0,min=size==4?0:-radius;return delta.getY()<=0&&delta.getY()>=-depth&&delta.getX()>=min&&delta.getX()<=radius&&delta.getZ()>=min&&delta.getZ()<=radius;}
 static boolean loaded(NativeLegacyLandingEntity root){var world=root.getLevel();for(var offset:LegacyLandingLayout.reserved(Math.max(root.progress(),root.targetDistance()),root.settings().size()))if(!NativeLegacyLandingBlock.loaded(world,root.getBlockPos().offset(offset.x,offset.y,offset.z)))return false;return true;}
 private static NativeRawCell capture(ServerLevel world,BlockPos pos){var state=world.getBlockState(pos);var tile=world.getBlockEntity(pos);return new NativeRawCell(pos,state,tile==null?null:tile.saveWithFullMetadata(world.registryAccess()),2*1024*1024);}
 private static boolean same(ServerLevel world,NativeRawCell cell){if(!NativeLegacyLandingBlock.loaded(world,cell.pos)||world.getBlockState(cell.pos)!=cell.state)return false;var tile=world.getBlockEntity(cell.pos);return cell.hasTile()?tile!=null&&tile.saveWithFullMetadata(world.registryAccess()).equals(cell.tile()):tile==null;}
 private static void publish(ServerLevel world,NativeRawCell cell){if(!world.setBlock(cell.pos,cell.state,18)&&world.getBlockState(cell.pos)!=cell.state)throw new IllegalStateException("Telescopic cell publication refused");if(world.getBlockState(cell.pos)!=cell.state)throw new IllegalStateException("Telescopic cell changed during publication");if(cell.hasTile()){var tile=cell.stage(world,t->t instanceof NativeLegacyLandingEntity,tagsEqual());world.setBlockEntity(tile);if(!same(world,cell))throw new IllegalStateException("Telescopic tile publication changed data");}else if(world.getBlockEntity(cell.pos)!=null)throw new IllegalStateException("Unexpected telescopic tile after AIR publication");}
 private static java.util.function.BiPredicate<CompoundTag,CompoundTag> tagsEqual(){return CompoundTag::equals;}
 static Plan prepare(NativeLegacyLandingEntity root,NativeLegacyLandingData.Configuration next,float distance){
  if(!root.current()||!root.physicalRoot()||!(root.getLevel() instanceof ServerLevel world)||com.vandorlabs.neoforge.ramp.NativeRampHeldOwners.blocked(world,root.getBlockPos()))throw new IllegalArgumentException("Unavailable telescopic owner");
  var desired=new LinkedHashSet<BlockPos>();for(var offset:LegacyLandingLayout.reserved(distance,next.size())){var pos=root.getBlockPos().offset(offset.x,offset.y,offset.z);if(world.isOutsideBuildHeight(pos)||!NativeLegacyLandingBlock.loaded(world,pos)||!world.getWorldBorder().isWithinBounds(pos)||com.vandorlabs.neoforge.ramp.NativeRampHeldOwners.blocked(world,pos))throw new IllegalArgumentException("Load the complete clear telescopic footprint");desired.add(pos);}
  var before=new ArrayList<NativeRawCell>();var after=new ArrayList<NativeRawCell>();
  for(var pos:desired){var state=world.getBlockState(pos);var tile=world.getBlockEntity(pos);boolean own=tile instanceof NativeLegacyLandingEntity helper&&root.ownHelper(helper);
   if(own&&((NativeLegacyLandingEntity)tile).identity().equals(root.identity()))continue;
   if(own&&!((NativeLegacyLandingEntity)tile).pristine()||!own&&(!state.isAir()||tile!=null))throw new IllegalArgumentException("Telescopic footprint has a foreign block or opaque proxy");
   var original=capture(world,pos);var replacement=root.getBlockState().setValue(NativeLegacyLandingBlock.LOWER,true).setValue(NativeLegacyLandingBlock.EXTENDED,true);var fresh=new NativeLegacyLandingEntity(pos,replacement);fresh.setLevel(world);fresh.helperOf(root);var target=new NativeRawCell(pos,replacement,fresh.saveWithFullMetadata(world.registryAccess()),65536);target.stage(world,t->t instanceof NativeLegacyLandingEntity,tagsEqual());before.add(original);after.add(target);
  }
  for(int depth=0;depth<=5;depth++)for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++){if(depth==0&&x==0&&z==0)continue;var pos=root.getBlockPos().offset(x,-depth,z);if(desired.contains(pos)||!NativeLegacyLandingBlock.loaded(world,pos))continue;var tile=world.getBlockEntity(pos);if(!(tile instanceof NativeLegacyLandingEntity helper)||!root.ownHelper(helper))continue;if(!helper.pristine())throw new IllegalArgumentException("Opaque telescopic proxy retained");if(com.vandorlabs.neoforge.ramp.NativeRampHeldOwners.blocked(world,pos))throw new IllegalArgumentException("Telescopic proxy is reserved");before.add(capture(world,pos));after.add(new NativeRawCell(pos,Blocks.AIR.defaultBlockState(),null,65536));}
  return new Plan(root,List.copyOf(before),List.copyOf(after));
 }
 static final class Plan {
  final NativeLegacyLandingEntity root;final ServerLevel world;final List<NativeRawCell> before,after;final CompoundTag original;private int written;
  Plan(NativeLegacyLandingEntity root,List<NativeRawCell> before,List<NativeRawCell> after){this.root=root;world=(ServerLevel)root.getLevel();this.before=before;this.after=after;original=root.saveWithFullMetadata(world.registryAccess());}
  void install(){if(before.isEmpty())return;var prior=ACTIVE.get();ACTIVE.set(new Scope(world,root.getBlockPos()));try{for(int i=0;i<before.size();i++){if(!root.current()||!same(world,before.get(i)))throw new IllegalStateException("Telescopic preimage changed");written=i+1;publish(world,after.get(i));}for(var cell:after)if(!same(world,cell))throw new IllegalStateException("Telescopic publication callback changed a cell");}catch(RuntimeException failed){rollback(failed);throw new IllegalArgumentException("Telescopic reservation was not published",failed);}finally{if(prior==null)ACTIVE.remove();else ACTIVE.set(prior);}}
  void undo(){if(written==0)return;var prior=ACTIVE.get();ACTIVE.set(new Scope(world,root.getBlockPos()));try{var failure=new IllegalStateException("Telescopic placement rollback");rollback(failure);if(failure.getSuppressed().length>0)throw failure;written=0;}finally{if(prior==null)ACTIVE.remove();else ACTIVE.set(prior);}}
  private void rollback(RuntimeException failed){boolean restored=true;for(int i=written-1;i>=0;i--)try{if(!same(world,after.get(i)))throw new IllegalStateException("Foreign cell changed during telescopic rollback");publish(world,before.get(i));}catch(RuntimeException error){restored=false;failed.addSuppressed(error);}if(restored)written=0;if(!restored){var details=new CompoundTag();var cells=new ListTag();for(int i=0;i<before.size();i++){var entry=new CompoundTag();entry.putLong("Pos",before.get(i).pos.asLong());entry.put("State",NbtUtils.writeBlockState(before.get(i).state));if(before.get(i).hasTile())entry.put("Tile",before.get(i).tile());cells.add(entry);}details.put("Before",cells);root.failRecovery(original,details);}}
 }
 static void orphan(NativeLegacyLandingEntity helper){var world=(ServerLevel)helper.getLevel();if(!helper.owned()||!helper.pristine()||!NativeLegacyLandingBlock.loaded(world,helper.ownerPos()))return;var owner=world.getBlockEntity(helper.ownerPos());if(owner instanceof NativeLegacyLandingEntity root&&root.ownHelper(helper))return;if(!world.getBlockState(helper.ownerPos()).isAir())return;var prior=ACTIVE.get();ACTIVE.set(new Scope(world,helper.ownerPos()));try{world.removeBlock(helper.getBlockPos(),false);}finally{if(prior==null)ACTIVE.remove();else ACTIVE.set(prior);}}
 static void remove(NativeLegacyLandingEntity root){var world=(ServerLevel)root.getLevel();var prior=ACTIVE.get();ACTIVE.set(new Scope(world,root.getBlockPos()));try{for(int depth=0;depth<=5;depth++)for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++){var pos=root.getBlockPos().offset(x,-depth,z);if(!NativeLegacyLandingBlock.loaded(world,pos)||!(world.getBlockEntity(pos) instanceof NativeLegacyLandingEntity helper))continue;if(helper==root||root.ownHelper(helper)&&helper.pristine())world.removeBlock(pos,false);}}finally{if(prior==null)ACTIVE.remove();else ACTIVE.set(prior);}}
 private NativeLegacyFootprints(){}
}
